5	// Re-export the pure helpers so existing call sites (`@/utils/auth-redirect`)
6	// keep working without every caller switching to the new module. The side-effectful
7	// `redirectOnAuthFailure` lives here; pure logic lives in `./redirect-safety`.
8	export {
9	  AUTH_REASON_PARAM,
10	  AUTH_REASON_PROTECTED_MEMO,
11	  AUTH_REDIRECT_PARAM,
12	  appendSearchParams,
13	  buildAuthRoute,
14	  getSafeRedirectPath,
15	  isPublicRoute,
16	  shouldGatePrivateInstance,
